// Complete Multilingual Riddle Database - 1000 Unique Traditional Riddles
// Telugu, English & Hindi with canonical answers, multilingual hints, and explanations

export interface RiddleLanguageData {
  question: string;
  answer: string;
  acceptedAnswers: string[];
}

export interface Riddle {
  id: number;
  telugu: RiddleLanguageData;
  english: RiddleLanguageData;
  hindi: RiddleLanguageData;
  canonicalAnswer: {
    en: string;
    te: string;
    hi: string;
  };
  acceptedAnswers: string[];
  answer: string[]; // Backwards compatibility
  hint: {
    te: string;
    en: string;
    hi: string;
  };
  explanation: {
    te: string;
    en: string;
    hi: string;
  };
  difficulty: 'easy' | 'medium' | 'hard' | 'expert' | 'genius';
  correctOptionId?: string | number;
}

// Helper to get difficulty based on level
export const getDifficulty = (level: number): Riddle['difficulty'] => {
  if (level <= 100) return 'easy';
  if (level <= 250) return 'medium';
  if (level <= 400) return 'hard';
  if (level <= 600) return 'hard';
  if (level <= 800) return 'expert';
  return 'genius';
};

// Check if level is premium
export const isPremiumLevel = (level: number): boolean => level > 400;

