// Helper to get localized question
export const getRiddleQuestion = (riddle: Riddle, lang: 'te' | 'en' | 'hi' = 'te'): string => {
  if (lang === 'en') return riddle.english.question;
  if (lang === 'hi') return riddle.hindi.question;
  return riddle.telugu.question;
};

// Helper to get localized answer
export const getRiddleAnswer = (riddle: Riddle, lang: 'te' | 'en' | 'hi' = 'te'): string => {
  if (lang === 'en') return riddle.canonicalAnswer.en;
  if (lang === 'hi') return riddle.canonicalAnswer.hi;
  return riddle.canonicalAnswer.te;
};

// Helper to get localized hint
export const getRiddleHint = (riddle: Riddle, lang: 'te' | 'en' | 'hi' = 'te'): string => {
  if (lang === 'en') return riddle.hint.en;
  if (lang === 'hi') return riddle.hint.hi;
  return riddle.hint.te;
};

// Get riddle by level
export const getRiddle = (level: number): Riddle => {
  const riddle = riddlesData.find(r => r.id === level);
  if (!riddle) {
    // Fallback for any missing levels
    return {
      id: level,
      telugu: {
        question: `స్థాయి ${level} పొడుపు కథ: ఆకాశంలో మెరిసే తార. అది ఏమిటి?`,
        answer: "నక్షత్రం",
        acceptedAnswers: ["నక్షత్రం", "నక్షత్రాలు", "చుక్క"]
      },
      english: {
        question: `Level ${level} riddle: Star twinkling in the sky. What is it?`,
        answer: "Star",
        acceptedAnswers: ["star", "stars"]
      },
      hindi: {
        question: `स्तर ${level} पहेली: रात के आसमान में चमकता तारा। वह क्या है?`,
        answer: "तारा",
        acceptedAnswers: ["तारा", "तारे", "सितारा"]
      },
      canonicalAnswer: { en: "Star", te: "నక్షత్రం", hi: "तारा" },
      acceptedAnswers: ["star", "stars", "నక్షత్రం", "నక్షత్రాలు", "చుక్క", "तारा", "तारे", "सितारा"],
      answer: ["star", "stars", "నక్షత్రం", "నక్షత్రాలు", "చుక్క", "तारा", "तारे", "सितारा"],
      hint: {
        en: "Look up at the night sky",
        te: "రాత్రి పూట ఆకాశం వైపు చూడండి",
        hi: "रात के समय आकाश की ओर देखें"
      },
      explanation: {
        en: "Stars glitter and shine across the night sky.",
        te: "రాత్రి పూట ఆకాశంలో నక్షత్రాలు మినుకుమినుకుమంటూ వెలుగుతాయి.",
        hi: "रात के समय आकाश में तारे चमकते हैं।"
      },
      difficulty: getDifficulty(level)
    };
  }
  return riddle;
};

// Get all riddles for a difficulty
export const getRiddlesByDifficulty = (difficulty: Riddle['difficulty']): Riddle[] => {
  return riddlesData.filter(r => r.difficulty === difficulty);
};

// Total riddle count
export const getTotalRiddleCount = (): number => riddlesData.length;

// Premium riddle count
export const getPremiumRiddleCount = (): number => riddlesData.filter(r => isPremiumLevel(r.id)).length;

export default riddlesData;
